\begin{tikzpicture}[every node/.style={font=\scriptsize}]
\node[draw=NebulaNavy,thick,rounded corners,align=left,text width=5.1cm,inner sep=6pt] (b1) at (0,0)
{\textbf{Adición}\\[2pt] $>\!C\!=\!C\!<\; +\;$reactivo $\rightarrow\; >\!C\!-\!C\!<$\\[2pt] Catalizador Pt/Pd/Ni (H$_2$); medio ácido o éter (H$_2$O, HX); regla de Markovnikov; no exige calor.};
\node[draw=NebulaNavy,thick,rounded corners,align=left,text width=5.1cm,inner sep=6pt] (b2) at (6.3,0)
{\textbf{Eliminación}\\[2pt] $>\!C(H)\!-\!C(X)\!<\; \rightarrow\; >\!C\!=\!C\!<\;+\;HX$\\[2pt] Base fuerte y calor, disolvente alcohólico (haluros) o H$_2$SO$_4$ y calor (alcoholes); regla de Saytzeff.};
\node[draw=NebulaNavy,thick,rounded corners,align=left,text width=5.1cm,inner sep=6pt] (b3) at (12.6,0)
{\textbf{Sustitución}\\[2pt] $R\!-\!A\;+\;B\; \rightarrow\; R\!-\!B\;+\;A$\\[2pt] Medio básico acuoso, frío (SN2, sustratos 1\textsuperscript{os}); disolvente polar, sin base fuerte (SN1, sustratos 3\textsuperscript{os}).};
\node[draw=NebulaNavy,thick,rounded corners,align=left,text width=5.1cm,inner sep=6pt] (b4) at (0,-3.7)
{\textbf{Oxidación-reducción}\\[2pt] cambia el estado de oxidación del C del sustrato\\[2pt] Oxidante fuerte (KMnO$_4$, Cr$_2$O$_7^{2-}$) o suave (PCC) para oxidar; H$_2$+catalizador o hidruros para reducir.};
\node[draw=NebulaNavy,thick,rounded corners,align=left,text width=5.1cm,inner sep=6pt] (b5) at (6.3,-3.7)
{\textbf{Esterificación}\\[2pt] $R\!-\!COOH + HO\!-\!R' \rightarrow R\!-\!COO\!-\!R' + H_2O$\\[2pt] Catalizador ácido (H$_2$SO$_4$) y calor; reacción reversible, en equilibrio.};
\node[draw=NebulaNavy,thick,rounded corners,align=left,text width=5.1cm,inner sep=6pt] (b6) at (12.6,-3.7)
{\textbf{Polimerización}\\[2pt] $n\,(\text{monómero}) \rightarrow (\text{unidad repetitiva})_n$\\[2pt] Adición: doble enlace, iniciador, calor o presión, sin subproducto. Condensación: pérdida de H$_2$O por unión.};
\end{tikzpicture}
